#' Time shift plot for finite concurrent filters generated by an X-13ARIMA-SEATS 
#' SEATS seasonal adjustment run. 
#'
#' Generate time shift plot of the finite concurrent SEATS seasonal adjustment 
#' and trend filters from a SEATS adjustment from a \code{seas} object generated by the \code{seasonal}
#' package. For more information on SEATS and SEATS input options in X-13ARIMA-SEATS, 
#' \insertCite{@see Section 7.14 of @Census2025}{blsplotGG}.
#'
#' Version 2.4, 2/17/2026
#'
#' @param seas_obj \code{seas} object generated from a call of \code{seas} on a single time series
#'        This is a required entry.
#' @param main_title Character string; main title of plot. 
#'        A title will be generated if no title is specified.
#' @param sub_title Character string; subtitle of plot. There is no default subtitle.
#' @param this_y_label Character string; y-axis label for plot.
#'        Default is \code{"Time Shift"}.
#' @param this_x_label Label for X axis. Default is \code{"Cycles per Year"}.
#' @param do_grid Logical scalar; indicates if certain plots will have grid lines.
#'        Default is no grid lines. 
#' @param do_background Logical scalar; indicates grey background included in plot.
#'        Default is no grey background;
#' @param line_color Character vector of length two; colors used for the squared gain 
#'        in the plot.  For a listing of R color codes, 
#'        see \insertCite{rchartsColors;textual}{blsplotGG}.
#'        Default is \code{NULL}, which indicates that the palette specified 
#'        in \code{this_palette} is used to generate colors for this plot.
#' @param this_palette Color used for lines in plot. 
#'        Default is the \code{RColorBrewer} palette \code{"Paired"} \insertCite{RColorBrewer}{blsplotGG}.
#' @param this_legend_title Title for legend.  Default is \code{"Filter"}
#' @param this_legend_title_size integer scalar; Size of the legend title.
#'        Default is \code{12}.
#' @param this_legend_text_size integer scalar; Size of the legend title.
#'        Default is \code{10}.
#' @param this_legend_position character String; The position of the legend, which can be one of
#'        \code{top}, \code{bottom}, \code{left}, \code{right}.
#'        Default is \code{right}.
#' @param this_legend_space integer scalar; Space between legend and plot in points.
#'        Default is \code{10}.
#' @return A \code{ggplot} object which generates a plot of the squared gains for filters 
#'         generated by the SEATS seasonal factors. 
#'         If SEATS seaonal adjustment (with \code{finite = yes}) not producted,  
#'         print out error message and return NULL. 
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples
#' shoes_time_shift <- 
#'    seasonal::seas(shoes2008, arima.model = "(0 1 1)(0 1 1)", 
#'                   transform.function = "log", 
#'                   forecast.maxlead = 36,
#'                   check.print = c( 'pacf', 'pacfplot' ), 
#'                   seats.finite = "yes",
#'                   seats.save = c( 'tac', 'ttc' ) )
#' p_time_shift <- plot_time_shift(shoes_time_shift, 
#'		sub_title = "US Shoe Sales",
#'		this_palette = "Set2")
#' @importFrom Rdpack reprompt
#' @export
plot_time_shift <- function(
	seas_obj = NULL, 
	main_title = NULL, 
	sub_title = NULL, 
	this_y_label = "Time Shift", 
	this_x_label = "Cycles per Year",
	do_grid = FALSE,
	do_background = FALSE,
	line_color = NULL,
	this_palette = "Paired", 
	this_legend_title = "Filter",
	this_legend_title_size = 12,
	this_legend_text_size = 10,
	this_legend_position = "right",
	this_legend_space = 10) {
    # Author: Brian C. Monsell (OEUS) Version 2.4, 2/17/2026

    # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
        cat("must specify a seas object")
		return(NULL)
    } else {
    # check if a seas object is specified for \code{seas_obj}
        if (!inherits(seas_obj, "seas")) {
            cat("First argument must be a seas object")
			return(NULL)
        }
    }

	if (!("seatsadj" %in% names(seasonal::udg(seas_obj)))) {
		cat("Must use SEATS to generate seasonal adjustment")
		return(NULL)
	}
	
	# check legend options 
	position_all <- c("top", "bottom", "left", "right")
	if(sum(match(position_all, this_legend_position), na.rm = TRUE) == 0) {
        cat(paste("Legend position choice not valid:", this_legend_position))
		return(NULL)
	}
	
	if(this_legend_text_size <= 0) {
        cat(paste("Legend text size not valid (must be greater than zero):", 
		           this_legend_text_size))
		return(NULL)
	}
	
	if(this_legend_title_size <= 0) {
        cat(paste("Legend title text size not valid (must be greater than zero):", 
		           this_legend_title_size))
		return(NULL)
	}

	this_time_shift_sa <- seasonal::series(seas_obj, "tac")
	if (is.null(this_time_shift_sa)) {
		cat("Must specify seats.finite = 'yes' when generating seas object")
		return(NULL)
	}
	
	this_time_shift_trn <- seasonal::series(seas_obj, "ttc")
	
	main_title <- "Time Shift for the Concurrent SA and Trend Filter"
	
	num_color <- 2
	if (is.null(line_color)) {
        line_color <- RColorBrewer::brewer.pal(3, this_palette)[1:num_color]
    } else {
        if (length(line_color) < num_color) {
	    if (length(line_color) > 1) {
                warning("Number of line colors specified less than series plotted.")
                warning("Will use colorRampPalette to increase number of colors.")
                line_color <- grDevices::colorRampPalette(line_color)(num_color)
            }
        }
    }

	this_freq_index <- as.numeric(this_time_shift_sa[,1]) > 0.0
	this_freq_index[1] <- TRUE
	
	this_shift_df <- data.frame(
		freq = as.numeric(this_time_shift_sa[,1])[this_freq_index],
		sa = as.numeric(this_time_shift_sa[,2])[this_freq_index],
		trn  = as.numeric(this_time_shift_trn[,2])[this_freq_index])  %>%
		dplyr::select(.data$freq, .data$sa, .data$trn) %>%
          tidyr::gather(key = "shift", value = "value", -.data$freq) 
	
	p_time_shift <- 
		ggplot2::ggplot(this_shift_df) + 
        ggplot2::geom_line(ggplot2::aes(x = .data$freq, 
                                        y = .data$value, 
                                        color = .data$shift)) + 
        ggplot2::scale_color_manual(labels = c("SA", "Trend"), 
                                    values = line_color) +
        ggplot2::labs(title = main_title,
                      subtitle = sub_title,
                      x = this_x_label,
                      y = this_y_label) +
        ggplot2::guides(color = ggplot2::guide_legend(this_legend_title))
	
	# remove grey background if \code{do_background = FALSE} 
    if (!do_background) {
		p_time_shift <- p_time_shift + ggplot2::theme_bw()
    }
      
	# remove grid lines
    if (!do_grid) {
		p_time_shift <- p_time_shift + 
			ggplot2::theme(panel.grid.major = ggplot2::element_blank(), 
			               panel.grid.minor = ggplot2::element_blank())
    }
	
	p_time_shift <- p_time_shift +
		ggplot2::theme(legend.text = ggplot2::element_text(size = this_legend_text_size),
					   legend.title = ggplot2::element_text(size = this_legend_title_size),
				       legend.position = this_legend_position,
				       legend.box.spacing = ggplot2::unit(this_legend_space, "pt"))
	
	return(p_time_shift)
}